/** Device-only Worker: PCM is generated by the transport's caller. */
import {parentPort, workerData} from 'node:worker_threads';
let output, closed = false;
const ready = (async () => {
  const {createOutput} = await import(workerData.outputModule ?? new URL('./output_audify.mjs', import.meta.url).href);
  output = await createOutput({...workerData.outputOptions, sampleRate: workerData.sampleRate,
    bufferFrames: workerData.bufferFrames, onDrain: () => {
      if (!closed && output) parentPort.postMessage({type: 'consumed', state: output.getState()});
    }, onError: error => {if (!closed) parentPort.postMessage({type: 'fatal', error: error.message});}});
  parentPort.postMessage({type: 'ready', frames: output.frames, state: output.getState()});
})();
ready.catch(error => parentPort.postMessage({type: 'fatal', error: error.message}));
let commands = Promise.resolve();
parentPort.on('message', message => {
  commands = commands.then(async () => {
    try {
      await ready;
      if (message.op === 'write') {await output.write(message.pcm); return;}
      if (message.op === 'close') closed = true;
      if (!['start', 'stop', 'close'].includes(message.op)) throw new Error('Invalid output operation');
      await output[message.op]();
      parentPort.postMessage({type: 'reply', id: message.id, state: output.getState()});
    } catch (error) {parentPort.postMessage({type: 'fatal', error: error.message});}
  });
});
